/**
 * Mock interview availability.
 *
 * Generated by the same rules the real availability engine will apply, so the
 * booking UI is exercised against realistic data rather than a tidy list that
 * hides the awkward cases:
 *
 *   · working days only, Monday to Friday
 *   · 09:00–17:00 UK, in 30-minute slots
 *   · a slot must END by 17:00, so 16:30 is the last one
 *   · 11:30–12:30 UK is blocked for lunch
 *   · nothing inside the next 24 hours (minimum notice)
 *   · a scattering already taken, so "unavailable" is visible in the UI
 *
 * Times are held as UTC instants and converted for display — the candidate
 * sees their own timezone and the UK time, never a bare number that could mean
 * either.
 */

const SLOT_MINUTES = 30;
const DAY_START = 9;
const DAY_END = 17;
const LUNCH_START = 11.5;
const LUNCH_END = 12.5;
const NOTICE_HOURS = 24;
const DAYS_AHEAD = 14;

/**
 * The UK's offset from UTC on a given date: +1 during British Summer Time,
 * 0 otherwise. India and South Africa observe no daylight saving, so the UK is
 * the only clock that moves — which is exactly why availability is anchored
 * here and converted outward.
 */
function ukOffsetHours(date) {
  // Asks Intl directly for the zone's offset at this instant ("GMT+1" in
  // summer, "GMT" in winter). Reconstructing it by round-tripping through
  // toLocaleString is a well-known source of off-by-an-hour bugs.
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Europe/London',
    timeZoneName: 'shortOffset',
  }).formatToParts(date);

  const name = parts.find((p) => p.type === 'timeZoneName')?.value ?? 'GMT';
  const match = name.match(/GMT([+-]\d{1,2})/);
  return match ? Number(match[1]) : 0;
}

export function generateSlots({ now = new Date(), daysAhead = DAYS_AHEAD } = {}) {
  const days = [];
  const earliest = new Date(now.getTime() + NOTICE_HOURS * 3600 * 1000);

  for (let dayOffset = 0; dayOffset <= daysAhead; dayOffset += 1) {
    const date = new Date(now);
    date.setUTCDate(date.getUTCDate() + dayOffset);
    date.setUTCHours(0, 0, 0, 0);

    const weekday = date.getUTCDay();
    if (weekday === 0 || weekday === 6) continue; // Mon–Fri only

    const offset = ukOffsetHours(date);
    const slots = [];

    for (let hour = DAY_START; hour + SLOT_MINUTES / 60 <= DAY_END; hour += SLOT_MINUTES / 60) {
      // Lunch: any slot overlapping the block is removed entirely.
      const slotEnd = hour + SLOT_MINUTES / 60;
      if (hour < LUNCH_END && slotEnd > LUNCH_START) continue;

      const start = new Date(date);
      start.setUTCHours(Math.floor(hour) - offset, (hour % 1) * 60, 0, 0);

      if (start < earliest) continue; // inside the notice window

      // Deterministic pseudo-availability so the mock does not reshuffle on
      // every render — a slot that vanishes between paints looks like a bug.
      const seed = (start.getUTCDate() * 37 + start.getUTCHours() * 13 + start.getUTCMinutes()) % 7;
      slots.push({
        startsAt: start.toISOString(),
        endsAt: new Date(start.getTime() + SLOT_MINUTES * 60000).toISOString(),
        taken: seed === 0 || seed === 3,
      });
    }

    if (slots.length > 0) days.push({ date: date.toISOString(), slots });
  }

  return days;
}

